

#include <pybind11/pybind11.h>

#include "_wrapper_cache.h"
#include "_return_caster.h"

// Forward declarations of the per-type register_* functions generated by Gluecodium. Each
// top-level LIME type (except type aliases and lambdas, which need no binding) emits one
// `void register_<Name>(py::module_&)` from its own translation unit; this module entry point
// aggregates them into a single CPython extension module.
void register_Errors(py::module_& module);
void register_ErrorsInterface(py::module_& module);
void register_FooBar(py::module_& module);
void register_Payload(py::module_& module);
void register_SomeInternalEnum(py::module_& module);
void register_SomeTypeCollection(py::module_& module);
void register_SomethingBadHappenedError(py::module_& module);
void register_UseTcException(py::module_& module);
void register_WithPayloadError(py::module_& module);
void register_WithStringError(py::module_& module);

// pybind11 3.x no longer provides the `py` namespace alias by default.
namespace py = pybind11;

PYBIND11_MODULE(generated, m) {
    m.doc() = "Generated Python bindings for the 'generated' extension module.";

    register_Errors(m);
    register_ErrorsInterface(m);
    register_FooBar(m);
    register_Payload(m);
    register_SomeInternalEnum(m);
    register_SomeTypeCollection(m);
    register_SomethingBadHappenedError(m);
    register_UseTcException(m);
    register_WithPayloadError(m);
    register_WithStringError(m);
}
